-- Ship It: every backend file in run order. Generated by tools/sql_all.sh; edit the source files, not this.
-- Paste into Supabase dashboard -> SQL Editor -> New query, and Run once. Safe to re-run.

-- ======== supabase_setup.sql ========
-- Ship It — Supabase setup
-- Run this once in your project's SQL editor (Supabase dashboard → SQL Editor → New query).
--
-- Passwords are never stored here. Supabase Auth owns them in auth.users, hashed with
-- bcrypt, along with sessions and password resets. This table only holds game progress.
--
-- The anon key shipped in the page is a PUBLISHABLE key: it identifies the project, not a
-- user. Everything below depends on row-level security to keep one player out of another
-- player's row, so do not skip the policies.

-- ---------------------------------------------------------------- progress table
create table if not exists public.profiles (
  id          uuid primary key references auth.users (id) on delete cascade,
  profile     jsonb       not null default '{}'::jsonb,   -- the P object (xp, coins, seen, badges…)
  course      jsonb,                                      -- an in-flight Subject Course, or null
  updated_at  timestamptz not null default now(),
  created_at  timestamptz not null default now()
);

comment on table public.profiles is 'Per-user Ship It progress. One row per auth user.';

-- ---------------------------------------------------------------- display name
-- Added after the first release, so this whole file is safe to run again on an existing
-- project: every statement below is guarded.
alter table public.profiles add column if not exists username text;

-- Case-insensitive uniqueness. The app never needs to read other people's rows to check
-- whether a name is free - it simply tries to save and handles the 23505 the index raises,
-- which keeps row-level security airtight while still preventing duplicates.
create unique index if not exists profiles_username_lower_key
  on public.profiles (lower(username));

do $$
begin
  if not exists (select 1 from pg_constraint where conname = 'profiles_username_shape') then
    alter table public.profiles
      add constraint profiles_username_shape
      check (username is null or username ~ '^[A-Za-z0-9_]{3,20}$');
  end if;
end
$$;

-- ---------------------------------------------------------------- row level security
-- Without this, the publishable key would let anyone read every row.
alter table public.profiles enable row level security;

drop policy if exists "read own profile"   on public.profiles;
drop policy if exists "insert own profile" on public.profiles;
drop policy if exists "update own profile" on public.profiles;
drop policy if exists "delete own profile" on public.profiles;

create policy "read own profile"   on public.profiles
  for select using (auth.uid() = id);

create policy "insert own profile" on public.profiles
  for insert with check (auth.uid() = id);

create policy "update own profile" on public.profiles
  for update using (auth.uid() = id) with check (auth.uid() = id);

create policy "delete own profile" on public.profiles
  for delete using (auth.uid() = id);

-- ---------------------------------------------------------------- housekeeping
create or replace function public.touch_updated_at()
returns trigger
language plpgsql
as $$
begin
  new.updated_at = now();
  return new;
end;
$$;

drop trigger if exists profiles_touch_updated_at on public.profiles;
create trigger profiles_touch_updated_at
  before update on public.profiles
  for each row execute function public.touch_updated_at();

-- Give every new account an empty row so the client never has to special-case "first save".
create or replace function public.handle_new_user()
returns trigger
language plpgsql
security definer set search_path = public
as $$
begin
  insert into public.profiles (id, profile)
  values (new.id, '{}'::jsonb)
  on conflict (id) do nothing;
  return new;
end;
$$;

drop trigger if exists on_auth_user_created on auth.users;
create trigger on_auth_user_created
  after insert on auth.users
  for each row execute function public.handle_new_user();

-- ---------------------------------------------------------------- verify
-- Expect four policies and rowsecurity = true.
-- select tablename, rowsecurity from pg_tables where tablename = 'profiles';
-- select policyname, cmd from pg_policies where tablename = 'profiles';

-- ======== supabase_add_username.sql ========
-- ============================================================================
--  Ship It — add usernames to an existing project
--  Run this once in: Supabase dashboard → SQL Editor → New query → Run
--  Safe to run more than once. It does not touch your existing rows or policies.
-- ============================================================================

-- 1. the column itself
alter table public.profiles
  add column if not exists username text;

-- 2. case-insensitive uniqueness, so "GigaChad" and "gigachad" can't both exist.
--    The app never reads other people's rows to check availability — it just tries to
--    save and treats the error this index raises as "that name is taken", which keeps
--    row-level security strict.
create unique index if not exists profiles_username_lower_key
  on public.profiles (lower(username));

-- 3. shape: 3–20 characters, letters, numbers and underscore only
do $$
begin
  if not exists (select 1 from pg_constraint where conname = 'profiles_username_shape') then
    alter table public.profiles
      add constraint profiles_username_shape
      check (username is null or username ~ '^[A-Za-z0-9_]{3,20}$');
  end if;
end
$$;

-- 4. let PostgREST notice the new column straight away instead of waiting for its
--    schema cache to refresh on its own
notify pgrst, 'reload schema';

-- ============================================================================
--  Verify — this should return one row: username | text
-- ============================================================================
select column_name, data_type
from information_schema.columns
where table_schema = 'public'
  and table_name   = 'profiles'
  and column_name  = 'username';

-- ======== supabase_casino.sql ========
-- ============================================================================
--  Ship It — Casino (server-authoritative)
--  Run once in: Supabase dashboard → SQL Editor → New query → Run
--  Safe to re-run.
--
--  The whole point of this file: the browser never decides an outcome. Every spin,
--  card and payout happens inside these functions, on the database, where the player
--  cannot reach. The chips table has NO client write policy at all - the only way a
--  balance changes is through a security-definer function below.
-- ============================================================================

-- ---------------------------------------------------------------- wallet
create table if not exists public.wallets (
  user_id        uuid primary key references auth.users (id) on delete cascade,
  chips          bigint      not null default 0 check (chips >= 0),
  last_grant_at  timestamptz,
  lifetime_won   bigint      not null default 0,
  lifetime_lost  bigint      not null default 0,
  updated_at     timestamptz not null default now()
);

alter table public.wallets enable row level security;

-- Read your own balance. Deliberately NO insert/update/delete policy: a client that
-- tries to write its own chips gets nothing, whatever it sends.
drop policy if exists "read own wallet" on public.wallets;
create policy "read own wallet" on public.wallets
  for select using (auth.uid() = user_id);

-- ---------------------------------------------------------------- blackjack hands
-- The shoe and the dealer's hole card live here and are never exposed: there is no
-- select policy, so only the functions below can see them.
create table if not exists public.bj_hands (
  user_id     uuid primary key references auth.users (id) on delete cascade,
  bet         bigint      not null,
  deck        int[]       not null,       -- remaining cards, 1..52, server eyes only
  player      int[]       not null,
  dealer      int[]       not null,
  state       text        not null default 'active',   -- active | done
  outcome     text,
  updated_at  timestamptz not null default now()
);
alter table public.bj_hands enable row level security;   -- no policies at all = no client access

-- ---------------------------------------------------------------- house log
create table if not exists public.casino_log (
  id         bigserial primary key,
  user_id    uuid not null references auth.users (id) on delete cascade,
  game       text not null,
  bet        bigint not null,
  delta      bigint not null,
  detail     jsonb,
  created_at timestamptz not null default now()
);
alter table public.casino_log enable row level security;
drop policy if exists "read own log" on public.casino_log;
create policy "read own log" on public.casino_log
  for select using (auth.uid() = user_id);

-- ============================================================================
--  helpers
-- ============================================================================
create or replace function public.wallet_row()
returns public.wallets
language plpgsql security definer set search_path = public
as $$
declare w public.wallets;
begin
  if auth.uid() is null then raise exception 'not signed in'; end if;
  insert into public.wallets (user_id, chips, last_grant_at)
    values (auth.uid(), 0, null)
    on conflict (user_id) do nothing;
  select * into w from public.wallets where user_id = auth.uid();
  return w;
end $$;

-- Balance + whether today's free chips are available.
create or replace function public.casino_state()
returns jsonb
language plpgsql security definer set search_path = public
as $$
declare w public.wallets; ready boolean;
begin
  w := public.wallet_row();
  ready := (w.last_grant_at is null or now() - w.last_grant_at > interval '20 hours');
  return jsonb_build_object(
    'chips', w.chips,
    'grantReady', ready,
    'nextGrant', case when ready then null else w.last_grant_at + interval '20 hours' end,
    'won', w.lifetime_won, 'lost', w.lifetime_lost);
end $$;

-- Free daily chips, so an empty wallet is never a dead end.
create or replace function public.casino_grant()
returns jsonb
language plpgsql security definer set search_path = public
as $$
declare w public.wallets; amount bigint := 250;
begin
  w := public.wallet_row();
  if w.last_grant_at is not null and now() - w.last_grant_at <= interval '20 hours' then
    return jsonb_build_object('ok', false, 'reason', 'already claimed',
                              'nextGrant', w.last_grant_at + interval '20 hours', 'chips', w.chips);
  end if;
  update public.wallets
     set chips = chips + amount, last_grant_at = now(), updated_at = now()
   where user_id = auth.uid()
  returning * into w;
  insert into public.casino_log (user_id, game, bet, delta, detail)
       values (auth.uid(), 'grant', 0, amount, '{}'::jsonb);
  return jsonb_build_object('ok', true, 'granted', amount, 'chips', w.chips);
end $$;

-- ============================================================================
--  roulette - single zero, 37 pockets
--  red/black pay 1:1, green pays 35:1
-- ============================================================================
create or replace function public.casino_roulette(bet bigint, pick text)
returns jsonb
language plpgsql security definer set search_path = public
as $$
declare
  w public.wallets;
  pocket int;
  colour text;
  payout bigint := 0;
  won boolean := false;
  reds int[] := array[1,3,5,7,9,12,14,16,18,19,21,23,25,27,30,32,34,36];
begin
  w := public.wallet_row();
  if pick not in ('red','black','green') then raise exception 'bad pick'; end if;
  if bet <= 0 then raise exception 'bet must be positive'; end if;
  if w.chips < bet then
    return jsonb_build_object('ok', false, 'reason', 'not enough chips', 'chips', w.chips);
  end if;

  -- the spin happens here, on the server, after the bet is locked in
  pocket := floor(random() * 37)::int;                    -- 0..36
  colour := case when pocket = 0 then 'green'
                 when pocket = any(reds) then 'red' else 'black' end;

  if colour = pick then
    won := true;
    payout := case when pick = 'green' then bet * 35 else bet end;
  end if;

  update public.wallets
     set chips = chips + (case when won then payout else -bet end),
         lifetime_won  = lifetime_won  + (case when won then payout else 0 end),
         lifetime_lost = lifetime_lost + (case when won then 0 else bet end),
         updated_at = now()
   where user_id = auth.uid()
  returning * into w;

  insert into public.casino_log (user_id, game, bet, delta, detail)
       values (auth.uid(), 'roulette', bet,
               case when won then payout else -bet end,
               jsonb_build_object('pocket', pocket, 'colour', colour, 'pick', pick));

  return jsonb_build_object('ok', true, 'pocket', pocket, 'colour', colour,
                            'won', won, 'payout', payout, 'chips', w.chips);
end $$;

-- ============================================================================
--  blackjack - dealer stands on 17, blackjack pays 3:2
--  cards are 1..52; rank = ((c - 1) % 13) + 1, suit = (c - 1) / 13
-- ============================================================================
create or replace function public.bj_value(cards int[])
returns int language plpgsql immutable as $$
declare c int; r int; total int := 0; aces int := 0;
begin
  foreach c in array cards loop
    r := ((c - 1) % 13) + 1;
    if r = 1 then aces := aces + 1; total := total + 11;
    elsif r >= 10 then total := total + 10;
    else total := total + r; end if;
  end loop;
  while total > 21 and aces > 0 loop total := total - 10; aces := aces - 1; end loop;
  return total;
end $$;

create or replace function public.bj_public(h public.bj_hands, reveal boolean)
returns jsonb language plpgsql stable set search_path = public as $$
begin
  return jsonb_build_object(
    'state', h.state, 'bet', h.bet, 'outcome', h.outcome,
    'player', h.player, 'playerValue', public.bj_value(h.player),
    -- the hole card stays hidden until the hand is settled
    'dealer', case when reveal then h.dealer else h.dealer[1:1] end,
    'dealerValue', case when reveal then public.bj_value(h.dealer)
                        else public.bj_value(h.dealer[1:1]) end);
end $$;

create or replace function public.bj_start(bet bigint)
returns jsonb
language plpgsql security definer set search_path = public
as $$
declare w public.wallets; deck int[]; h public.bj_hands; pv int; dv int;
begin
  w := public.wallet_row();
  if bet <= 0 then raise exception 'bet must be positive'; end if;
  if w.chips < bet then
    return jsonb_build_object('ok', false, 'reason', 'not enough chips', 'chips', w.chips);
  end if;
  delete from public.bj_hands where user_id = auth.uid();

  select array_agg(c order by random()) into deck
    from generate_series(1, 52) c;                       -- shuffled, server side only

  update public.wallets set chips = chips - bet, updated_at = now()
   where user_id = auth.uid() returning * into w;        -- stake is taken up front

  insert into public.bj_hands (user_id, bet, deck, player, dealer)
       values (auth.uid(), bet, deck[5:52],
               array[deck[1], deck[3]], array[deck[2], deck[4]])
  returning * into h;

  pv := public.bj_value(h.player); dv := public.bj_value(h.dealer);
  if pv = 21 or dv = 21 then                             -- naturals settle immediately
    if pv = 21 and dv = 21 then
      update public.wallets set chips = chips + h.bet where user_id = auth.uid();
      h.outcome := 'push';
    elsif pv = 21 then
      update public.wallets set chips = chips + h.bet + (h.bet * 3 / 2),
             lifetime_won = lifetime_won + (h.bet * 3 / 2) where user_id = auth.uid();
      h.outcome := 'blackjack';
    else
      update public.wallets set lifetime_lost = lifetime_lost + h.bet where user_id = auth.uid();
      h.outcome := 'dealer blackjack';
    end if;
    update public.bj_hands set state = 'done', outcome = h.outcome where user_id = auth.uid()
    returning * into h;
    insert into public.casino_log (user_id, game, bet, delta, detail)
      values (auth.uid(), 'blackjack', h.bet,
              case h.outcome when 'blackjack' then (h.bet * 3 / 2) when 'push' then 0 else -h.bet end,
              jsonb_build_object('outcome', h.outcome));
  end if;

  select * into w from public.wallets where user_id = auth.uid();
  return public.bj_public(h, h.state = 'done') || jsonb_build_object('ok', true, 'chips', w.chips);
end $$;

create or replace function public.bj_hit()
returns jsonb
language plpgsql security definer set search_path = public
as $$
declare h public.bj_hands; w public.wallets;
begin
  select * into h from public.bj_hands where user_id = auth.uid();
  if h is null or h.state <> 'active' then raise exception 'no hand in play'; end if;

  h.player := h.player || h.deck[1];
  h.deck := h.deck[2:array_length(h.deck, 1)];

  if public.bj_value(h.player) > 21 then
    h.state := 'done'; h.outcome := 'bust';
    update public.wallets set lifetime_lost = lifetime_lost + h.bet, updated_at = now()
     where user_id = auth.uid();
    insert into public.casino_log (user_id, game, bet, delta, detail)
      values (auth.uid(), 'blackjack', h.bet, -h.bet, '{"outcome":"bust"}'::jsonb);
  end if;

  update public.bj_hands set player = h.player, deck = h.deck, state = h.state,
         outcome = h.outcome, updated_at = now()
   where user_id = auth.uid() returning * into h;

  select * into w from public.wallets where user_id = auth.uid();
  return public.bj_public(h, h.state = 'done') || jsonb_build_object('ok', true, 'chips', w.chips);
end $$;

create or replace function public.bj_stand()
returns jsonb
language plpgsql security definer set search_path = public
as $$
declare h public.bj_hands; w public.wallets; pv int; dv int; delta bigint := 0;
begin
  select * into h from public.bj_hands where user_id = auth.uid();
  if h is null or h.state <> 'active' then raise exception 'no hand in play'; end if;

  while public.bj_value(h.dealer) < 17 loop                -- dealer draws to 17
    h.dealer := h.dealer || h.deck[1];
    h.deck := h.deck[2:array_length(h.deck, 1)];
  end loop;

  pv := public.bj_value(h.player); dv := public.bj_value(h.dealer);
  if dv > 21 or pv > dv then
    h.outcome := case when dv > 21 then 'dealer bust' else 'win' end;
    delta := h.bet;
    update public.wallets set chips = chips + h.bet * 2, lifetime_won = lifetime_won + h.bet,
           updated_at = now() where user_id = auth.uid();
  elsif pv = dv then
    h.outcome := 'push';
    update public.wallets set chips = chips + h.bet, updated_at = now() where user_id = auth.uid();
  else
    h.outcome := 'lose'; delta := -h.bet;
    update public.wallets set lifetime_lost = lifetime_lost + h.bet, updated_at = now()
     where user_id = auth.uid();
  end if;

  update public.bj_hands set dealer = h.dealer, deck = h.deck, state = 'done',
         outcome = h.outcome, updated_at = now()
   where user_id = auth.uid() returning * into h;

  insert into public.casino_log (user_id, game, bet, delta, detail)
    values (auth.uid(), 'blackjack', h.bet, delta, jsonb_build_object('outcome', h.outcome));

  select * into w from public.wallets where user_id = auth.uid();
  return public.bj_public(h, true) || jsonb_build_object('ok', true, 'chips', w.chips);
end $$;

create or replace function public.bj_current()
returns jsonb
language plpgsql security definer set search_path = public
as $$
declare h public.bj_hands;
begin
  select * into h from public.bj_hands where user_id = auth.uid();
  if h is null then return jsonb_build_object('ok', true, 'state', 'none'); end if;
  return public.bj_public(h, h.state = 'done') || jsonb_build_object('ok', true);
end $$;

-- ============================================================================
--  cash out - chips become study coins
--  Only this direction exists. Study coins are written by the browser, so letting
--  them buy chips would let anyone mint chips and then take them off another player.
-- ============================================================================
create or replace function public.casino_cash_out(amount bigint)
returns jsonb
language plpgsql security definer set search_path = public
as $$
declare w public.wallets; coins bigint;
begin
  w := public.wallet_row();
  if amount <= 0 then raise exception 'amount must be positive'; end if;
  if w.chips < amount then
    return jsonb_build_object('ok', false, 'reason', 'not enough chips', 'chips', w.chips);
  end if;
  coins := amount / 5;                                    -- 5 chips = 1 study coin
  if coins <= 0 then
    return jsonb_build_object('ok', false, 'reason', 'need at least 5 chips', 'chips', w.chips);
  end if;
  update public.wallets set chips = chips - (coins * 5), updated_at = now()
   where user_id = auth.uid() returning * into w;
  insert into public.casino_log (user_id, game, bet, delta, detail)
    values (auth.uid(), 'cashout', 0, -(coins * 5), jsonb_build_object('coins', coins));
  return jsonb_build_object('ok', true, 'coins', coins, 'chips', w.chips);
end $$;

-- ============================================================================
--  permissions - only signed-in users, and only through these functions
-- ============================================================================
revoke all on function public.wallet_row() from public, anon;
do $$
declare f text;
begin
  foreach f in array array['casino_state()','casino_grant()','casino_roulette(bigint,text)',
                           'bj_start(bigint)','bj_hit()','bj_stand()','bj_current()',
                           'casino_cash_out(bigint)']
  loop
    execute format('revoke all on function public.%s from public, anon;', f);
    execute format('grant execute on function public.%s to authenticated;', f);
  end loop;
end $$;

notify pgrst, 'reload schema';

-- ============================================================================
--  verify - expect wallets/bj_hands/casino_log with rowsecurity = true,
--  and bj_hands with zero policies (nobody reads the shoe)
-- ============================================================================
select tablename, rowsecurity,
       (select count(*) from pg_policies p where p.tablename = t.tablename) as policies
  from pg_tables t
 where schemaname = 'public' and tablename in ('wallets','bj_hands','casino_log')
 order by tablename;

-- ======== supabase_casino_v2.sql ========
-- ============================================================================
--  Ship It — Casino v2
--   · shared roulette: one wheel for everyone, a new round every 25 seconds
--   · study coins → chips (capped, see the note below)
--   · retention: old rounds, bets, hands and logs delete themselves
--  Run after supabase_casino.sql. Safe to re-run.
-- ============================================================================

-- ---------------------------------------------------------------- house secret
-- Seeds the wheel. No policies, so no client can ever read it: without this a player
-- could compute the next pocket themselves, since the outcome is derived from the
-- round number rather than rolled at a random moment.
create table if not exists public.casino_secret (
  k text primary key,
  v text not null
);
alter table public.casino_secret enable row level security;

insert into public.casino_secret (k, v)
  values ('wheel', encode(gen_random_bytes(32), 'hex'))
  on conflict (k) do nothing;

-- ---------------------------------------------------------------- rounds & bets
create table if not exists public.roulette_rounds (
  id          bigint primary key,            -- floor(epoch / 25): the round IS the clock
  pocket      int,
  colour      text,
  resolved_at timestamptz,
  created_at  timestamptz not null default now()
);
alter table public.roulette_rounds enable row level security;
drop policy if exists "read rounds" on public.roulette_rounds;
create policy "read rounds" on public.roulette_rounds for select using (auth.uid() is not null);

create table if not exists public.roulette_bets (
  id         bigserial primary key,
  round_id   bigint not null,
  user_id    uuid   not null references auth.users (id) on delete cascade,
  username   text,                            -- denormalised so the live table needs no joins
  pick       text   not null check (pick in ('red','black','green')),
  amount     bigint not null check (amount > 0),
  payout     bigint,
  settled    boolean not null default false,
  created_at timestamptz not null default now()
);
create index if not exists roulette_bets_round_idx on public.roulette_bets (round_id);
alter table public.roulette_bets enable row level security;

-- Everyone at the table sees the bets on the table - that is the point of playing together.
drop policy if exists "read table bets" on public.roulette_bets;
create policy "read table bets" on public.roulette_bets
  for select using (auth.uid() is not null);
-- but only the functions below may write one
drop policy if exists "no client writes" on public.roulette_bets;

-- ---------------------------------------------------------------- retention
-- The user was right that this fills up: a round every 25 seconds is ~3,500 rows a day
-- before anyone even bets. Nothing here needs a scheduler - each call sweeps a little.
create or replace function public.casino_sweep()
returns void
language plpgsql security definer set search_path = public
as $$
begin
  delete from public.roulette_bets   where created_at < now() - interval '2 hours';
  delete from public.roulette_rounds where created_at < now() - interval '2 hours';
  delete from public.casino_log      where created_at < now() - interval '7 days';
  delete from public.bj_hands        where state = 'done' and updated_at < now() - interval '1 day';
end $$;

-- ---------------------------------------------------------------- the wheel
create or replace function public.roulette_now()
returns bigint language sql stable as $$
  select floor(extract(epoch from now()) / 25)::bigint;
$$;

-- Outcome is a pure function of (round number, secret). Every player who asks gets the
-- same answer, so no background worker has to be running for the wheel to have spun.
create or replace function public.roulette_pocket(round bigint)
returns int
language plpgsql security definer set search_path = public
as $$
declare s text; h text;
begin
  select v into s from public.casino_secret where k = 'wheel';
  h := md5(s || ':' || round::text);
  return (('x' || substr(h, 1, 8))::bit(32)::bigint % 37)::int;
end $$;

create or replace function public.roulette_colour(pocket int)
returns text language sql immutable as $$
  select case when pocket = 0 then 'green'
              when pocket = any (array[1,3,5,7,9,12,14,16,18,19,21,23,25,27,30,32,34,36])
              then 'red' else 'black' end;
$$;

-- Settle every round whose 25 seconds are up but whose bets have not been paid.
create or replace function public.roulette_settle()
returns void
language plpgsql security definer set search_path = public
as $$
declare r record; p int; c text;
begin
  for r in
    select distinct b.round_id
      from public.roulette_bets b
     where b.settled = false and b.round_id < public.roulette_now()
  loop
    p := public.roulette_pocket(r.round_id);
    c := public.roulette_colour(p);

    insert into public.roulette_rounds (id, pocket, colour, resolved_at)
         values (r.round_id, p, c, now())
    on conflict (id) do update set pocket = excluded.pocket, colour = excluded.colour,
                                   resolved_at = excluded.resolved_at;

    -- winners are paid, losers already had the stake taken when they bet
    update public.wallets w
       set chips = w.chips + b.amount * (case when b.pick = 'green' then 36 else 2 end),
           lifetime_won = w.lifetime_won + b.amount * (case when b.pick = 'green' then 35 else 1 end),
           updated_at = now()
      from public.roulette_bets b
     where b.round_id = r.round_id and b.settled = false and b.pick = c and w.user_id = b.user_id;

    update public.roulette_bets b
       set settled = true,
           payout = case when b.pick = c
                         then b.amount * (case when b.pick = 'green' then 36 else 2 end)
                         else 0 end
     where b.round_id = r.round_id and b.settled = false;

    update public.wallets w
       set lifetime_lost = w.lifetime_lost + b.amount
      from public.roulette_bets b
     where b.round_id = r.round_id and b.pick <> c and w.user_id = b.user_id
       and b.payout = 0;
  end loop;
end $$;

-- One call the client can poll: settles what is due, sweeps old rows, and returns the
-- state of the table - the clock, this round's bets from everyone, and the last result.
create or replace function public.roulette_table()
returns jsonb
language plpgsql security definer set search_path = public
as $$
declare cur bigint; ends timestamptz; last record; bets jsonb; mine jsonb; w public.wallets;
begin
  w   := public.wallet_row();
  cur := public.roulette_now();
  perform public.roulette_settle();
  if random() < 0.05 then perform public.casino_sweep(); end if;   -- amortised cleanup

  ends := to_timestamp((cur + 1) * 25);

  select * into last from public.roulette_rounds
   where resolved_at is not null order by id desc limit 1;

  select coalesce(jsonb_agg(jsonb_build_object(
           'who', coalesce(b.username, 'player'), 'pick', b.pick, 'amount', b.amount,
           'me', b.user_id = auth.uid()) order by b.id), '[]'::jsonb)
    into bets
    from public.roulette_bets b where b.round_id = cur;

  select coalesce(jsonb_agg(jsonb_build_object('pick', pick, 'amount', amount)), '[]'::jsonb)
    into mine
    from public.roulette_bets where round_id = cur and user_id = auth.uid();

  return jsonb_build_object(
    'round', cur,
    'endsAt', ends,
    'secondsLeft', greatest(0, round(extract(epoch from (ends - now()))))::int,
    'open', extract(epoch from (ends - now())) > 3,      -- no more bets in the last 3 seconds
    'bets', bets, 'mine', mine, 'chips', w.chips,
    'last', case when last is null then null else
      jsonb_build_object('round', last.id, 'pocket', last.pocket, 'colour', last.colour) end);
end $$;

create or replace function public.roulette_bet(pick text, amount bigint)
returns jsonb
language plpgsql security definer set search_path = public
as $$
declare w public.wallets; cur bigint; ends timestamptz; nm text;
begin
  w := public.wallet_row();
  if pick not in ('red','black','green') then raise exception 'bad pick'; end if;
  if amount <= 0 then raise exception 'bet must be positive'; end if;
  if w.chips < amount then
    return jsonb_build_object('ok', false, 'reason', 'not enough chips', 'chips', w.chips);
  end if;

  cur  := public.roulette_now();
  ends := to_timestamp((cur + 1) * 25);
  if extract(epoch from (ends - now())) <= 3 then
    return jsonb_build_object('ok', false, 'reason', 'no more bets — wait for the next round',
                              'chips', w.chips);
  end if;

  select username into nm from public.profiles where id = auth.uid();

  update public.wallets set chips = chips - amount, updated_at = now()
   where user_id = auth.uid() returning * into w;

  insert into public.roulette_bets (round_id, user_id, username, pick, amount)
       values (cur, auth.uid(), coalesce(nm, 'player'), pick, amount);

  return jsonb_build_object('ok', true, 'chips', w.chips, 'round', cur);
end $$;

-- ---------------------------------------------------------------- coins → chips
-- The reverse of cashing out, and the weaker half of the pair: study coins are written by
-- the browser, so the server cannot verify the player really had them. The daily cap is
-- what keeps a forged balance from becoming unlimited chips to take off someone in a duel.
create or replace function public.casino_buy_chips(coins bigint)
returns jsonb
language plpgsql security definer set search_path = public
as $$
declare w public.wallets; got bigint; used bigint; cap bigint := 1000;
begin
  w := public.wallet_row();
  if coins <= 0 then raise exception 'amount must be positive'; end if;
  got := coins * 5;                                   -- 1 study coin = 5 chips, the cash-out rate

  select coalesce(sum(delta), 0) into used
    from public.casino_log
   where user_id = auth.uid() and game = 'buyin' and created_at > now() - interval '24 hours';

  if used + got > cap then
    return jsonb_build_object('ok', false,
      'reason', 'daily buy-in limit reached (' || cap || ' chips per 24h)',
      'remaining', greatest(0, cap - used), 'chips', w.chips);
  end if;

  update public.wallets set chips = chips + got, updated_at = now()
   where user_id = auth.uid() returning * into w;
  insert into public.casino_log (user_id, game, bet, delta, detail)
       values (auth.uid(), 'buyin', 0, got, jsonb_build_object('coins', coins));

  return jsonb_build_object('ok', true, 'chips', w.chips, 'got', got,
                            'remaining', cap - used - got);
end $$;

-- ---------------------------------------------------------------- permissions
do $$
declare f text;
begin
  foreach f in array array['roulette_table()','roulette_bet(text,bigint)',
                           'casino_buy_chips(bigint)','roulette_now()']
  loop
    execute format('revoke all on function public.%s from public, anon;', f);
    execute format('grant execute on function public.%s to authenticated;', f);
  end loop;
end $$;
revoke all on function public.roulette_pocket(bigint) from public, anon, authenticated;
revoke all on function public.roulette_settle() from public, anon, authenticated;
revoke all on function public.casino_sweep() from public, anon, authenticated;

notify pgrst, 'reload schema';

-- ---------------------------------------------------------------- verify
select 'rounds' as t, count(*) from public.roulette_rounds
union all select 'bets', count(*) from public.roulette_bets
union all select 'secret set', count(*) from public.casino_secret where k = 'wheel';

-- ======== supabase_duel.sql ========
-- ============================================================================
--  Ship It — Question Duel + roulette fix
--  Run after supabase_casino_v2.sql. Safe to re-run.
--
--  Two players, the same questions, chips on the line. Whoever answers wrong while the
--  other answers right hands over the pot. The server has to hold the answer key for that
--  to mean anything - otherwise each client simply claims it was right.
-- ============================================================================

-- ---------------------------------------------------------------- roulette fix
-- The old settle only touched rounds that had unpaid bets, so a round nobody bet on was
-- never written down and the wheel appeared frozen between players. Materialise the round
-- that just finished whenever anyone looks at the table.
create or replace function public.roulette_mark(round bigint)
returns void
language plpgsql security definer set search_path = public
as $$
declare p int;
begin
  if exists (select 1 from public.roulette_rounds where id = round) then return; end if;
  p := public.roulette_pocket(round);
  insert into public.roulette_rounds (id, pocket, colour, resolved_at)
       values (round, p, public.roulette_colour(p), now())
  on conflict (id) do nothing;
end $$;
revoke all on function public.roulette_mark(bigint) from public, anon, authenticated;

-- ---------------------------------------------------------------- answer key
-- One row, no policies: only the security-definer functions below can read it. If clients
-- could select from this table the duel would be a typing race with the answers on screen.
create table if not exists public.answer_key (
  id  int primary key,
  ans jsonb not null
);
alter table public.answer_key enable row level security;

